using System;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public static class VehicleShowroom {
 static int selected;static GameObject preview;static Camera camera;static RenderTexture texture;static string model;static float lastRender=-1;static string message;
 public static void Close(){if(camera!=null)camera.targetTexture=null;if(preview!=null)UnityEngine.Object.Destroy(preview);if(texture!=null){texture.Release();UnityEngine.Object.Destroy(texture);}preview=null;camera=null;texture=null;model=null;}
 static void Preview(Rect rect,VehicleSpec spec){if(model!=spec.id||preview==null){Close();preview=UnityEngine.Object.Instantiate(Resources.Load<GameObject>(spec.id));preview.name="Showroom model / visual only";preview.transform.position=new Vector3(300,-1400,0);foreach(var t in preview.GetComponentsInChildren<Transform>())t.gameObject.layer=31;var c=new GameObject("Showroom preview camera");c.transform.SetParent(preview.transform,false);camera=c.AddComponent<Camera>();camera.enabled=false;camera.fieldOfView=32;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.035f,.06f,.09f);camera.nearClipPlane=.05f;camera.farClipPlane=25;texture=new RenderTexture(720,420,16);texture.Create();camera.targetTexture=texture;var lamp=new GameObject("Showroom fill light");lamp.transform.SetParent(preview.transform,false);lamp.transform.localPosition=new Vector3(2,4,3);var light=lamp.AddComponent<Light>();light.type=LightType.Point;light.range=12;light.intensity=2;light.cullingMask=1<<31;model=spec.id;lastRender=-1;}
  if(Event.current.type==EventType.Repaint&&Time.unscaledTime-lastRender>.04f){lastRender=Time.unscaledTime;camera.transform.position=preview.transform.position+Quaternion.Euler(0,30+Time.unscaledTime*8,0)*new Vector3(0,1.9f,6.1f);camera.transform.LookAt(preview.transform.position+Vector3.up*.65f);camera.Render();}GUI.DrawTexture(rect,texture,ScaleMode.ScaleToFit,false);
 }
 public static void Draw(RivalRaceDirector director,Action back){GUI.depth=-1100;var matrix=GUI.matrix;GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1280f,Screen.height/800f,1));var color=GUI.color;GUI.color=new Color(.035f,.06f,.085f);GUI.DrawTexture(new Rect(0,0,1280,800),Texture2D.whiteTexture);GUI.color=color;var h=new GUIStyle(GUI.skin.label){fontSize=30,fontStyle=FontStyle.Bold};h.normal.textColor=new Color(.2f,.87f,.75f);var text=new GUIStyle(GUI.skin.label){fontSize=19,wordWrap=true};var button=new GUIStyle(GUI.skin.button){fontSize=19,wordWrap=true};button.normal.background=button.hover.background=button.active.background=Texture2D.whiteTexture;button.normal.textColor=button.hover.textColor=button.active.textColor=Color.white;var background=GUI.backgroundColor;GUI.backgroundColor=new Color(.12f,.22f,.28f);GUI.Label(new Rect(60,42,1150,46),"HARBOR VALE / CAR SHOWROOM",h);GUI.Label(new Rect(60,99,1150,35),director.Trial.Store.Profile.availableCredits.ToString("N0")+" cr · Complete cars, each with its own specifications",text);
  var cars=VehicleLineup.All;for(int i=0;i<cars.Length;i++)if(GUI.Button(new Rect(60+i*290,155,275,60),(selected==i?"✓ ":"")+cars[i].name+"\n"+cars[i].price.ToString("N0")+" cr",button))selected=i;var spec=cars[selected];var def=spec.workshop.stock;Preview(new Rect(60,240,680,380),spec);GUI.Label(new Rect(780,252,440,44),spec.name,h);GUI.Label(new Rect(780,306,440,270),spec.engine+"\n"+spec.stockDrive.ToUpperInvariant()+" · "+def.ratios.Length+" speeds\n"+ChassisTuning.CrankHp(def).ToString("F0")+" crank HP / "+ChassisTuning.EstimatedWhp(def).ToString("F0")+" WHP est\n"+spec.mass.ToString("N0")+" kg · "+def.redlineRpm.ToString("F0")+" rpm redline\n"+spec.length.ToString("F2")+" × "+spec.width.ToString("F2")+" × "+spec.height.ToString("F2")+" m\nWheelbase "+spec.wheelBase.ToString("F2")+" m\nModel-specific torque curves, gearing, tires and staged upgrade calibration.",text);
  GUI.enabled=director.Trial.Store.Profile.availableCredits>=spec.price;if(GUI.Button(new Rect(780,594,440,56),"Buy & select · "+spec.price.ToString("N0")+" cr",button)){try{director.Trial.Store.BuyVehicle(Guid.NewGuid().ToString("N"),spec.id,spec.price);director.ApplyVehicle();Close();back();}catch(Exception e){message=e.Message;}}GUI.enabled=true;GUI.Label(new Rect(60,651,1150,48),message??"New owned identity with stock hardware. Your other cars and their upgrades remain saved. Purchases and money commit together.",text);if(GUI.Button(new Rect(60,719,1160,43),"Back to owned cars",button)){Close();back();}GUI.backgroundColor=background;GUI.matrix=matrix;
 }
}
}
